}

package com.hardcorelifeline.checklist;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Getter;

/**
 * A checklist written as plain text, one rule per line (or separated by ';').
 *
 * <pre>
 * # comments start with '#'
 * equipped: Escape crystal      must be worn
 * Shark x10                     at least 10 (inventory or worn)
 * any: @teleport                at least one item from a built-in group
 * any: Ring of dueling | Games necklace
 * food x6                       at least 6 edible items
 * </pre>
 *
 * Item names match as case-insensitive prefixes, so "Ring of dueling" also matches "Ring of dueling(3)".
 */
public final class Checklist
{
	private static final Pattern COUNT = Pattern.compile("^(.*?)\\s+x\\s*(\\d+)$", Pattern.CASE_INSENSITIVE);

	@Getter
	private final List<Requirement> requirements;
	@Getter
	private final List<String> errors;

	private Checklist(List<Requirement> requirements, List<String> errors)
	{
		this.requirements = Collections.unmodifiableList(requirements);
		this.errors = Collections.unmodifiableList(errors);
	}

	public static Checklist parse(String text)
	{
		List<Requirement> requirements = new ArrayList<>();
		List<String> errors = new ArrayList<>();
		if (text == null)
		{
			return new Checklist(requirements, errors);
		}

		for (String raw : text.split("[\\r\\n;]+"))
		{
			String line = raw.trim();
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}

			String lower = line.toLowerCase(Locale.ROOT);
			if (lower.startsWith("any:"))
			{
				parseAny(line.substring(4).trim(), requirements, errors);
				continue;
			}

			boolean equipped = false;
			if (lower.startsWith("equipped:") || lower.startsWith("worn:"))
			{
				equipped = true;
				line = line.substring(line.indexOf(':') + 1).trim();
			}

			int minimum = 1;
			Matcher m = COUNT.matcher(line);
			if (m.matches())
			{
				line = m.group(1).trim();
				minimum = Math.max(1, Integer.parseInt(m.group(2)));
			}

			if (line.isEmpty())
			{
				errors.add("Empty item name in: " + raw.trim());
			}
			else if (!equipped && line.equalsIgnoreCase("food"))
			{
				requirements.add(new Requirement.Food(minimum));
			}
			else
			{
				requirements.add(new Requirement.Named(line, minimum, equipped));
			}
		}
		return new Checklist(requirements, errors);
	}

	private static void parseAny(String body, List<Requirement> requirements, List<String> errors)
	{
		int errorsBefore = errors.size();
		List<String> patterns = new ArrayList<>();
		List<String> labelParts = new ArrayList<>();
		for (String part : body.split("\\|"))
		{
			String p = part.trim();
			if (p.isEmpty())
			{
				continue;
			}
			if (p.startsWith("@"))
			{
				List<String> group = ItemGroups.get(p.substring(1));
				if (group == null)
				{
					errors.add("Unknown group " + p);
					continue;
				}
				patterns.addAll(group);
				labelParts.add("any " + p.substring(1).toLowerCase(Locale.ROOT));
			}
			else
			{
				patterns.add(p);
				labelParts.add(p);
			}
		}
		if (patterns.isEmpty())
		{
			if (errors.size() == errorsBefore)
			{
				errors.add("'any:' needs at least one item");
			}
			return;
		}
		String label = labelParts.size() == 1 ? capitalise(labelParts.get(0)) : "One of: " + String.join(" / ", labelParts);
		requirements.add(new Requirement.AnyOf(label, patterns));
	}

	private static String capitalise(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	public List<CheckResult> evaluate(List<HeldItem> items)
	{
		List<CheckResult> results = new ArrayList<>(requirements.size());
		for (Requirement r : requirements)
		{
			results.add(r.check(items));
		}
		return results;
	}
}

package com.hardcorelifeline.checklist;

import lombok.Value;

/**
 * One stack of items the player is carrying, as seen by the checklist.
 * Built from the player's own inventory and worn equipment only.
 */
@Value
public class HeldItem
{
	String name;
	int quantity;
	boolean equipped;
	boolean edible;
}

package com.hardcorelifeline.checklist;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;

/**
 * Built-in named groups that a checklist can reference with "@name".
 * Names are matched as case-insensitive prefixes, so "Ring of dueling" also matches "Ring of dueling(8)".
 */
public final class ItemGroups
{
	private static final Map<String, List<String>> GROUPS = new TreeMap<>();

	static
	{
		GROUPS.put("teleport", Collections.unmodifiableList(Arrays.asList(
			// Escape and respawn-style teleports
			"Escape crystal",
			"Royal seed pod",
			"Ectophial",
			// Charged jewellery
			"Ring of dueling",
			"Games necklace",
			"Amulet of glory",
			"Combat bracelet",
			"Skills necklace",
			"Ring of wealth",
			"Burning amulet",
			"Digsite pendant",
			"Necklace of passage",
			"Slayer ring",
			"Ring of the elements",
			"Xeric's talisman",
			"Drakan's medallion",
			"Teleport crystal",
			// Teleport tablets
			"Teleport to house",
			"Varrock teleport",
			"Lumbridge teleport",
			"Falador teleport",
			"Camelot teleport",
			"Ardougne teleport",
			"Watchtower teleport",
			"Kourend castle teleport"
		)));
	}

	private ItemGroups()
	{
	}

	/** Returns the item names in a built-in group, or null if the group does not exist. */
	public static List<String> get(String name)
	{
		return GROUPS.get(name.toLowerCase(Locale.ROOT));
	}

	public static Iterable<String> names()
	{
		return GROUPS.keySet();
	}
}

package com.hardcorelifeline.checklist;

import java.util.List;
import java.util.Locale;

/** One line of a checklist. Every requirement reads only what the player carries. */
public abstract class Requirement
{
	public abstract CheckResult check(List<HeldItem> items);

	static boolean matches(String itemName, String pattern)
	{
		return itemName != null && itemName.toLowerCase(Locale.ROOT).startsWith(pattern.toLowerCase(Locale.ROOT));
	}

	/** "Shark x10" or "equipped: Escape crystal": a named item, optionally a minimum count, optionally worn. */
	static final class Named extends Requirement
	{
		private final String pattern;
		private final int minimum;
		private final boolean mustBeEquipped;

		Named(String pattern, int minimum, boolean mustBeEquipped)
		{
			this.pattern = pattern;
			this.minimum = minimum;
			this.mustBeEquipped = mustBeEquipped;
		}

		@Override
		public CheckResult check(List<HeldItem> items)
		{
			int count = 0;
			for (HeldItem item : items)
			{
				if (matches(item.getName(), pattern) && (!mustBeEquipped || item.isEquipped()))
				{
					count += item.getQuantity();
				}
			}
			String label = pattern + (mustBeEquipped ? " (equipped)" : "") + (minimum > 1 ? " x" + minimum : "");
			String detail = minimum > 1 ? count + " / " + minimum : "";
			return new CheckResult(label, count >= minimum, detail);
		}
	}

	/** "any: Ring of dueling | Games necklace | @teleport": at least one of several items. */
	static final class AnyOf extends Requirement
	{
		private final String label;
		private final List<String> patterns;

		AnyOf(String label, List<String> patterns)
		{
			this.label = label;
			this.patterns = patterns;
		}

		@Override
		public CheckResult check(List<HeldItem> items)
		{
			for (HeldItem item : items)
			{
				for (String pattern : patterns)
				{
					if (matches(item.getName(), pattern))
					{
						return new CheckResult(label, true, item.getName());
					}
				}
			}
			return new CheckResult(label, false, "none");
		}
	}

	/** "food x8": at least N edible items in the inventory (worn items never count). */
	static final class Food extends Requirement
	{
		private final int minimum;

		Food(int minimum)
		{
			this.minimum = minimum;
		}

		@Override
		public CheckResult check(List<HeldItem> items)
		{
			int count = 0;
			for (HeldItem item : items)
			{
				if (item.isEdible() && !item.isEquipped())
				{
					count += item.getQuantity();
				}
			}
			return new CheckResult("Food x" + minimum, count >= minimum, count + " / " + minimum);
		}
	}
}

package com.hardcorelifeline;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.hardcorelifeline.checklist.CheckResult;
import com.hardcorelifeline.checklist.Checklist;
import com.hardcorelifeline.checklist.HeldItem;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class ChecklistTest
{
	private static HeldItem inv(String name, int qty)
	{
		return new HeldItem(name, qty, false, false);
	}

	private static HeldItem food(String name, int qty)
	{
		return new HeldItem(name, qty, false, true);
	}

	private static HeldItem worn(String name)
	{
		return new HeldItem(name, 1, true, false);
	}

	@Test
	public void escapeCrystalMustBeWorn()
	{
		Checklist c = Checklist.parse("equipped: Escape crystal");
		assertFalse(c.evaluate(Arrays.asList(inv("Escape crystal", 1))).get(0).isPassed());
		assertTrue(c.evaluate(Arrays.asList(worn("Escape crystal"))).get(0).isPassed());
	}

	@Test
	public void teleportGroupMatchesChargedJewellery()
	{
		Checklist c = Checklist.parse("any: @teleport");
		assertTrue(c.evaluate(Arrays.asList(inv("Ring of dueling(3)", 1))).get(0).isPassed());
		assertTrue(c.evaluate(Arrays.asList(worn("Amulet of glory(4)"))).get(0).isPassed());
		assertFalse(c.evaluate(Arrays.asList(inv("Shark", 5))).get(0).isPassed());
	}

	@Test
	public void foodCountsOnlyEdibleInventoryItems()
	{
		Checklist c = Checklist.parse("food x6");
		List<CheckResult> r = c.evaluate(Arrays.asList(food("Shark", 4), food("Karambwan", 1), inv("Coins", 500)));
		assertFalse(r.get(0).isPassed());
		assertEquals("5 / 6", r.get(0).getDetail());
		assertTrue(c.evaluate(Arrays.asList(food("Shark", 6))).get(0).isPassed());
	}

	@Test
	public void quantitiesAndCaseInsensitivePrefixes()
	{
		Checklist c = Checklist.parse("prayer potion x3");
		assertTrue(c.evaluate(Arrays.asList(inv("Prayer potion(4)", 2), inv("Prayer potion(2)", 1))).get(0).isPassed());
		assertFalse(c.evaluate(Arrays.asList(inv("Prayer potion(4)", 2))).get(0).isPassed());
	}

	@Test
	public void anyOfExplicitNames()
	{
		Checklist c = Checklist.parse("any: Ring of dueling | Games necklace");
		assertTrue(c.evaluate(Arrays.asList(inv("Games necklace(8)", 1))).get(0).isPassed());
		assertEquals("One of: Ring of dueling / Games necklace", c.getRequirements().size() == 1
			? c.evaluate(Arrays.asList(inv("Shark", 1))).get(0).getLabel() : "");
	}

	@Test
	public void commentsSemicolonsAndBadGroups()
	{
		Checklist c = Checklist.parse("# my list\nany: @nope; Shark x2 ;food x1");
		assertEquals(2, c.getRequirements().size());
		assertEquals(1, c.getErrors().size());
	}

	@Test
	public void defaultHardcoreListOnAGoodSetup()
	{
		Checklist c = Checklist.parse("equipped: Escape crystal\nany: @teleport\nfood x6");
		List<CheckResult> r = c.evaluate(Arrays.asList(worn("Escape crystal"), inv("Varrock teleport", 3), food("Monkfish", 8)));
		assertTrue(r.stream().allMatch(CheckResult::isPassed));
	}
}

